// bind is bindPreds plus the paging arguments, in suffix order.
func (q Query) bind(b *binder) []any {
	v := q.bindPreds(b)
	b.limit = q.limit
	v = append(v, &b.limit)
	// An offset of zero is absent from the statement, so binding it
	// would leave an argument nothing consumes.
	if q.offset > 0 {
		b.offset = q.offset
		v = append(v, &b.offset)
	}
	b.vals = v
	return v
}

// All runs the query and decodes every row.
func (q Query) All(ctx context.Context, ex runtime.Executor, dst []Row) ([]Row, error) {
	var sl runtime.Slab
	return q.AllInto(ctx, ex, dst, &sl)
}

// AllInto lets the caller own the string arena.
func (q Query) AllInto(ctx context.Context, ex runtime.Executor, dst []Row, sl *runtime.Slab) ([]Row, error) {
	if err := q.Err(); err != nil {
		return dst, err
	}
	var buf [21]runtime.Tok
	st := stmtFor(q.stream(&buf), q.offset > 0, q.lock)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return dst, st.Err
	}
	sl.Reserve(st.SlabHint())
	b := binders.Get()
	defer putBinder(b)

	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, Row{})
		if err := scan(rows.RawValues(), &dst[len(dst)-1], sl); err != nil {
			return dst, err
		}
	}
	st.ObserveSlab(sl.Size())
	return dst, rows.Err()
}

// One returns the first row, if any.
func (q Query) One(ctx context.Context, ex runtime.Executor) (Row, bool, error) {
	var sl runtime.Slab
	var buf [1]Row
	out, err := q.Limit(1).AllInto(ctx, ex, buf[:0], &sl)
	if err != nil || len(out) == 0 {
		return Row{}, false, err
	}
	return out[0], true, nil
}

// Count ignores Limit: counting a truncated set is a bug, not a feature.
func (q Query) Count(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.Err(); err != nil {
		return 0, err
	}
	if q.lock != 0 {
		return 0, errCountLocked
	}
	var buf [21]runtime.Tok
	st := countStmtFor(q.preds(&buf))
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	// bindPreds, not bind: a count has no LIMIT and no OFFSET. The old
	// form bound everything and sliced the last argument off, which was
	// the limit — unless Offset was set, in which case it silently kept
	// the limit and dropped the offset, and the statement mismatched.
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return 0, err
	}
	defer rows.Close()
	var n int64
	if rows.Next() {
		n = runtime.Int8(rows.RawValues()[0])
	}
	return n, rows.Err()
}

// Exists asks the one-bit question with a one-bit statement: SELECT 1,
// no ORDER BY, LIMIT 1. It was previously One() with the row thrown
// away, which projected every column AND carried the default ordering —
// measured on 50k rows, the planner top-N-sorted all 16,667 matches to
// return the "first" of an order nobody was going to read.
func (q Query) Exists(ctx context.Context, ex runtime.Executor) (bool, error) {
	if err := q.Err(); err != nil {
		return false, err
	}
	if q.lock != 0 {
		return false, errExistsLocked
	}
	var buf [21]runtime.Tok
	st := existsStmtFor(q.preds(&buf))
	if st.Err != nil {
		return false, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return false, err
	}
	defer rows.Close()
	return rows.Next(), rows.Err()
}

// Prepare resolves the structure and binds arguments without executing.
func (q Query) Prepare(b *Binder) (string, []any) {
	var buf [21]runtime.Tok
	return stmtFor(q.stream(&buf), q.offset > 0, q.lock).SQL, q.bind(b)
}

// QueueRow is the "Queue" projection: the same read, 19 column(s) instead of
// the whole row. Narrower tuples, no TOAST fetch for what nobody asked,
// and an index-only scan becomes POSSIBLE — the full-row read forecloses
// it by construction.
type QueueRow struct {
	ID                 [16]byte
	CreatedAt          time.Time
	UpdatedAt          time.Time
	ProjectID          [16]byte
	Kind               string
	Status             string
	InstanceID         runtime.Null[[16]byte]
	SourceDefinitionID runtime.Null[[16]byte]
	TargetDefinitionID runtime.Null[[16]byte]
	RequestedBy        string
	RequestedByID      [16]byte
	Reason             string
	Fingerprint        string
	ExpiresAt          time.Time
	DecidedBy          runtime.Null[string]
	DecidedByID        runtime.Null[[16]byte]
	DecisionReason     runtime.Null[string]
	DecidedAt          runtime.Null[time.Time]
	Outcome            runtime.JSON
}

const queuePrefix = `SELECT "id", "created_at", "updated_at", "project_id", "kind", "status", "instance_id", "source_definition_id", "target_definition_id", "requested_by", "requested_by_id", "reason", "fingerprint", "expires_at", "decided_by", "decided_by_id", "decision_reason", "decided_at", "outcome" FROM "deviation_requests"`

var (
	queueCache       = runtime.NewTreeCache()
	queueOffsetCache = runtime.NewTreeCache()
)

func queueStmtFor(toks []runtime.Tok, withOffset bool) *runtime.Stmt {
	c, suffix := queueCache, limitSuffix
	if withOffset {
		c, suffix = queueOffsetCache, limitOffsetSuffix
	}
	if st := c.Get(toks); st != nil {
		return st
	}
	return c.Put(toks, runtime.SpliceTree(queuePrefix, toks, lowering, suffix))
}

func scanQueue(rv [][]byte, r *QueueRow, sl *runtime.Slab) error {
	copy(r.ID[:], rv[0])
	r.CreatedAt = runtime.Timestamptz(rv[1])
	r.UpdatedAt = runtime.Timestamptz(rv[2])
	copy(r.ProjectID[:], rv[3])
	r.Kind = sl.Str(rv[4])
	r.Status = sl.Str(rv[5])
	r.InstanceID = runtime.Nullable(rv[6], runtime.UUID)
	r.SourceDefinitionID = runtime.Nullable(rv[7], runtime.UUID)
	r.TargetDefinitionID = runtime.Nullable(rv[8], runtime.UUID)
	r.RequestedBy = sl.Str(rv[9])
	copy(r.RequestedByID[:], rv[10])
	r.Reason = sl.Str(rv[11])
	r.Fingerprint = sl.Str(rv[12])
	r.ExpiresAt = runtime.Timestamptz(rv[13])
	r.DecidedBy = runtime.NullText(rv[14], sl)
	r.DecidedByID = runtime.Nullable(rv[15], runtime.UUID)
	r.DecisionReason = runtime.NullText(rv[16], sl)
	r.DecidedAt = runtime.Nullable(rv[17], runtime.Timestamptz)
	r.Outcome = runtime.JSON(runtime.JSONB(rv[18], sl))
	return nil
}

// AllQueue runs the query projected to QueueRow. Predicates, ordering, limit,
// offset and keyset all apply exactly as on All — a projection changes
// what a row CARRIES, never which rows qualify. (After takes the full Row;
// populate its ordering columns and the cursor works unchanged.)
func (q Query) AllQueue(ctx context.Context, ex runtime.Executor) ([]QueueRow, error) {
	var sl runtime.Slab
	return q.AllQueueInto(ctx, ex, nil, &sl)
}

// AllQueueInto lets the caller own the output slice and the arena, exactly
// as AllInto does — a projection's terminals mirror the full read's, so a
// hot loop reuses both and a benchmark compares like with like.
func (q Query) AllQueueInto(ctx context.Context, ex runtime.Executor, dst []QueueRow, sl *runtime.Slab) ([]QueueRow, error) {
	if err := q.Err(); err != nil {
		return dst, err
	}
	var buf [21]runtime.Tok
	st := queueStmtFor(q.stream(&buf), q.offset > 0)
	if st.Err != nil {
		return dst, st.Err
	}
	sl.Reserve(st.SlabHint())
	b := binders.Get()
	defer putBinder(b)
	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, QueueRow{})
		if err := scanQueue(rows.RawValues(), &dst[len(dst)-1], sl); err != nil {
			return dst, err
		}
	}
	st.ObserveSlab(sl.Size())
	return dst, rows.Err()
}

// OneQueue is AllQueue stopped at one row.
func (q Query) OneQueue(ctx context.Context, ex runtime.Executor) (QueueRow, bool, error) {
	out, err := q.Limit(1).AllQueue(ctx, ex)
	if err != nil || len(out) == 0 {
		return QueueRow{}, false, err
	}
	return out[0], true, nil
}

