func assignExcluded(c string) string { return assignFor[c] }

func stmtForInsert(mask uint64, conflict uint8) *runtime.Stmt {
	// The conflict clause is part of the statement, so it must be part of
	// the key. Packing it above the column bits keeps one cache for both.
	key := mask | uint64(conflict)<<nInsertable
	if st := insCache.Get(runtime.MaskKey{Dirty: key}); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := insReturning
	if conflict > 0 {
		suffix = upsertTail(conflict, mask) + insReturning
	}
	return insCache.Put(runtime.MaskKey{Dirty: key}, runtime.SpliceInsertWith(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// Insert writes the assigned columns and reads every column back, so
// database-computed values land in the returned Row rather than needing a
// second SELECT that would race every other writer.
func (n *Ins) Insert(ctx context.Context, ex runtime.Executor) (Row, error) {
	if n.set == 0 {
		return Row{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsert(n.set, n.conflict)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return Row{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.CreatedAt)
		case 2:
			args = append(args, n.row.UpdatedAt)
		case 3:
			args = append(args, n.row.ProjectID)
		case 4:
			args = append(args, n.row.Kind)
		case 5:
			args = append(args, n.row.Status)
		case 6:
			args = append(args, n.row.InstanceID.Arg())
		case 7:
			args = append(args, n.row.SourceDefinitionID.Arg())
		case 8:
			args = append(args, n.row.TargetDefinitionID.Arg())
		case 9:
			args = append(args, n.row.RequestedBy)
		case 10:
			args = append(args, n.row.RequestedByID)
		case 11:
			args = append(args, n.row.Reason)
		case 12:
			args = append(args, n.row.Command)
		case 13:
			args = append(args, n.row.Plan)
		case 14:
			args = append(args, n.row.Fingerprint)
		case 15:
			args = append(args, n.row.LiveKey.Arg())
		case 16:
			args = append(args, n.row.ApprovedInstances)
		case 17:
			args = append(args, n.row.ExpiresAt)
		case 18:
			args = append(args, n.row.DecidedBy.Arg())
		case 19:
			args = append(args, n.row.DecidedByID.Arg())
		case 20:
			args = append(args, n.row.DecisionReason.Arg())
		case 21:
			args = append(args, n.row.DecidedAt.Arg())
		case 22:
			args = append(args, n.row.Outcome)
		}
	}
	var out Row
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return out, err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return out, err
		}
		if n.conflict != 0 && n.conflict%2 == 1 {
			// DO NOTHING suppresses RETURNING, so no row means the row was
			// already there — the success case of an idempotent insert.
			return out, runtime.ErrConflict
		}
		return out, runtime.ErrNoRow
	}
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &out, &sl); err != nil {
		return out, err
	}
	return out, rows.Err()
}

// Inserts reports how many distinct INSERT column sets have compiled.
func Inserts() int { return insCache.Masks() }

// Insert writes one row and reads back every column, so database-computed
// defaults — a generated id, a now() timestamp — land in r rather than
// needing a second SELECT that would race every other writer.
//
// Every insertable column is written, including zero values. storm does
// not treat a zero as 'unset': that guess is why other ORMs cannot insert
// a false, a 0 or an empty string into a column with a default.
func Insert(ctx context.Context, ex runtime.Executor, r *Row) error {
	args := make([]any, 0, 23)
	args = append(args, r.ID)
	args = append(args, r.CreatedAt)
	args = append(args, r.UpdatedAt)
	args = append(args, r.ProjectID)
	args = append(args, r.Kind)
	args = append(args, r.Status)
	args = append(args, r.InstanceID.Arg())
	args = append(args, r.SourceDefinitionID.Arg())
	args = append(args, r.TargetDefinitionID.Arg())
	args = append(args, r.RequestedBy)
	args = append(args, r.RequestedByID)
	args = append(args, r.Reason)
	args = append(args, r.Command)
	args = append(args, r.Plan)
	args = append(args, r.Fingerprint)
	args = append(args, r.LiveKey.Arg())
	args = append(args, r.ApprovedInstances)
	args = append(args, r.ExpiresAt)
	args = append(args, r.DecidedBy.Arg())
	args = append(args, r.DecidedByID.Arg())
	args = append(args, r.DecisionReason.Arg())
	args = append(args, r.DecidedAt.Arg())
	args = append(args, r.Outcome)
	rows, err := ex.Query(ctx, insertSQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrNoRow
	}
	// The returned strings live as long as this Slab, and the Slab lives
	// as long as r — a Row from an insert owns its own arena, unlike a Row
	// from a scan, which shares the result set's.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), r, &sl); err != nil {
		return err
	}
	return rows.Err()
}

// copyCols is the fixed column list of a bulk load. Unlike Ins there is
// no mask: COPY sends one shape for the whole stream, so every row must
// supply every column and database defaults do not apply. Fill the row
// yourself, or use Create() per row and give up the bulk path.
var copyCols = []string{
	"id",
	"created_at",
	"updated_at",
	"project_id",
	"kind",
	"status",
	"instance_id",
	"source_definition_id",
	"target_definition_id",
	"requested_by",
	"requested_by_id",
	"reason",
	"command",
	"plan",
	"fingerprint",
	"live_key",
	"approved_instances",
	"expires_at",
	"decided_by",
	"decided_by_id",
	"decision_reason",
	"decided_at",
	"outcome",
}

// rowSource walks a []Row for CopyFrom without copying any of it.
type rowSource struct {
	rows []Row
	i    int
	buf  [23]any
}

func (s *rowSource) Next() bool {
	s.i++
	return s.i <= len(s.rows)
}

// Values reuses one buffer across every row, and fills it with POINTERS
// into the caller's slice rather than copies.
//
// Both halves matter. The driver consumes each slice before asking for
// the next, so one buffer is safe. And boxing a pointer into an `any`
// does not allocate while boxing a value does — at a thousand rows that
// is one allocation per column per row, or none. Measured: the first cut
// boxed values and cost 7 allocations per row.
func (s *rowSource) Values() []any {
	r := &s.rows[s.i-1]
	s.buf[0] = &r.ID
	s.buf[1] = &r.CreatedAt
	s.buf[2] = &r.UpdatedAt
	s.buf[3] = &r.ProjectID
	s.buf[4] = &r.Kind
	s.buf[5] = &r.Status
	s.buf[6] = r.InstanceID.Ptr()
	s.buf[7] = r.SourceDefinitionID.Ptr()
	s.buf[8] = r.TargetDefinitionID.Ptr()
	s.buf[9] = &r.RequestedBy
	s.buf[10] = &r.RequestedByID
	s.buf[11] = &r.Reason
	s.buf[12] = &r.Command
	s.buf[13] = &r.Plan
	s.buf[14] = &r.Fingerprint
	s.buf[15] = r.LiveKey.Ptr()
	s.buf[16] = &r.ApprovedInstances
	s.buf[17] = &r.ExpiresAt
	s.buf[18] = r.DecidedBy.Ptr()
	s.buf[19] = r.DecidedByID.Ptr()
	s.buf[20] = r.DecisionReason.Ptr()
	s.buf[21] = r.DecidedAt.Ptr()
	s.buf[22] = &r.Outcome
	return s.buf[:]
}

func (s *rowSource) Err() error { return nil }

// InsertAll bulk-loads rows through the driver's COPY protocol: ONE round
// trip regardless of row count, because COPY is a different wire path and
// not a faster loop over INSERT.
//
// It returns no rows. COPY has no RETURNING, so a caller who needs
// database-generated ids must supply them — which is why the primary key
// is in copyCols and must be set on every row.
func InsertAll(ctx context.Context, ex runtime.Executor, rows []Row) (int64, error) {
	if len(rows) == 0 {
		return 0, nil
	}
	src := &rowSource{rows: rows}
	return ex.CopyFrom(ctx, "deviation_requests", copyCols, src)
}

// InsertOp is an insert as a queueable statement. It writes every
// insertable column, because a batch of a thousand rows that each chose
// a different column set would compile a thousand statements and defeat
// the point of batching them.
//
// WantRows is false: a batched insert reports a count. Asking for
// RETURNING here would mean scanning a result per statement, which is
// exactly the per-row work a batch exists to avoid.
func InsertOp(r Row) runtime.BatchOp {
	var mask uint64
	mask |= 1 << 0
	mask |= 1 << 1
	mask |= 1 << 2
	mask |= 1 << 3
	mask |= 1 << 4
	mask |= 1 << 5
	mask |= 1 << 6
	mask |= 1 << 7
	mask |= 1 << 8
	mask |= 1 << 9
	mask |= 1 << 10
	mask |= 1 << 11
	mask |= 1 << 12
	mask |= 1 << 13
	mask |= 1 << 14
	mask |= 1 << 15
	mask |= 1 << 16
	mask |= 1 << 17
	mask |= 1 << 18
	mask |= 1 << 19
	mask |= 1 << 20
	mask |= 1 << 21
	mask |= 1 << 22
	st := stmtForInsertNoReturn(mask, 0)
	args := make([]any, 0, 23)
	args = append(args, r.ID)
	args = append(args, r.CreatedAt)
	args = append(args, r.UpdatedAt)
	args = append(args, r.ProjectID)
	args = append(args, r.Kind)
	args = append(args, r.Status)
	args = append(args, r.InstanceID.Arg())
	args = append(args, r.SourceDefinitionID.Arg())
	args = append(args, r.TargetDefinitionID.Arg())
	args = append(args, r.RequestedBy)
	args = append(args, r.RequestedByID)
	args = append(args, r.Reason)
	args = append(args, r.Command)
	args = append(args, r.Plan)
	args = append(args, r.Fingerprint)
	args = append(args, r.LiveKey.Arg())
	args = append(args, r.ApprovedInstances)
	args = append(args, r.ExpiresAt)
	args = append(args, r.DecidedBy.Arg())
	args = append(args, r.DecidedByID.Arg())
	args = append(args, r.DecisionReason.Arg())
	args = append(args, r.DecidedAt.Arg())
	args = append(args, r.Outcome)
	return runtime.BatchOp{SQL: st.SQL, Args: args}
}

// Op is this Ins as a queueable statement, conflict clause and all —
// the bulk upsert.
//
// InsertOp above takes a Row and writes every column, so a thousand of
// them share one statement. This takes the BUILDER, so it carries the
// mask and the ON CONFLICT the caller chose: ingesting a batch that
// should overwrite what is already there, or skip it, needs both and
// could otherwise only be done one round trip at a time.
//
// One statement per distinct (mask, conflict) pair, cached like every
// other. Assign the same columns on every row of a batch and it stays
// one; vary them and it is one per shape, which is the cost of asking.
//
// WantRows is false, as for InsertOp: a batch reports counts. A DO
// NOTHING that skipped a row is a zero in that count — the batch
// cannot say which rows were skipped, only how many.
func (n *Ins) Op() (runtime.BatchOp, error) {
	if n.set == 0 {
		return runtime.BatchOp{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsertNoReturn(n.set, n.conflict)
	if st.Err != nil {
		return runtime.BatchOp{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.CreatedAt)
		case 2:
			args = append(args, n.row.UpdatedAt)
		case 3:
			args = append(args, n.row.ProjectID)
		case 4:
			args = append(args, n.row.Kind)
		case 5:
			args = append(args, n.row.Status)
		case 6:
			args = append(args, n.row.InstanceID.Arg())
		case 7:
			args = append(args, n.row.SourceDefinitionID.Arg())
		case 8:
			args = append(args, n.row.TargetDefinitionID.Arg())
		case 9:
			args = append(args, n.row.RequestedBy)
		case 10:
			args = append(args, n.row.RequestedByID)
		case 11:
			args = append(args, n.row.Reason)
		case 12:
			args = append(args, n.row.Command)
		case 13:
			args = append(args, n.row.Plan)
		case 14:
			args = append(args, n.row.Fingerprint)
		case 15:
			args = append(args, n.row.LiveKey.Arg())
		case 16:
			args = append(args, n.row.ApprovedInstances)
		case 17:
			args = append(args, n.row.ExpiresAt)
		case 18:
			args = append(args, n.row.DecidedBy.Arg())
		case 19:
			args = append(args, n.row.DecidedByID.Arg())
		case 20:
			args = append(args, n.row.DecisionReason.Arg())
		case 21:
			args = append(args, n.row.DecidedAt.Arg())
		case 22:
			args = append(args, n.row.Outcome)
		}
	}
	return runtime.BatchOp{SQL: st.SQL, Args: args}, nil
}

// stmtForInsertNoReturn is stmtForInsert without RETURNING, for the
// batch path. Its own cache: the two differ by a suffix, and sharing
// one would hand a batch the statement that asks for rows back.
func stmtForInsertNoReturn(mask uint64, conflict uint8) *runtime.Stmt {
	key := mask | uint64(conflict)<<nInsertable
	if st := insOpCache.Get(runtime.MaskKey{Dirty: key}); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := ""
	if conflict > 0 {
		suffix = upsertTail(conflict, mask)
	}
	return insOpCache.Put(runtime.MaskKey{Dirty: key}, runtime.SpliceInsertWith(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// UpdateOp is this Mut's update as a queueable statement.
//
// The optimistic lock still applies, but the caller must check the
// affected count the batch reports: a stale write inside a batch is not
// an error the driver raises, it is a zero the caller has to notice.
//
// A server-side assignment is queued like any other, but the staged row
// is NOT refreshed: a batch reports counts, not rows. Use Update when
// the computed value is the thing you need.
func (m *Mut) UpdateOp() (runtime.BatchOp, bool) {
	if m.dirty == 0 && m.expr == 0 {
		return runtime.BatchOp{}, false
	}
	st := stmtForKey(m.key(), false)
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.ProjectID)
		case 2:
			args = append(args, m.row.Kind)
		case 3:
			args = append(args, m.row.Status)
		case 4:
			args = append(args, m.row.InstanceID.Arg())
		case 5:
			args = append(args, m.row.SourceDefinitionID.Arg())
		case 6:
			args = append(args, m.row.TargetDefinitionID.Arg())
		case 7:
			args = append(args, m.row.RequestedBy)
		case 8:
			args = append(args, m.row.RequestedByID)
		case 9:
			args = append(args, m.row.Reason)
		case 10:
			args = append(args, m.row.Command)
		case 11:
			args = append(args, m.row.Plan)
		case 12:
			args = append(args, m.row.Fingerprint)
		case 13:
			args = append(args, m.row.LiveKey.Arg())
		case 14:
			args = append(args, m.row.ApprovedInstances)
		case 15:
			args = append(args, m.row.ExpiresAt)
		case 16:
			args = append(args, m.row.DecidedBy.Arg())
		case 17:
			args = append(args, m.row.DecidedByID.Arg())
		case 18:
			args = append(args, m.row.DecisionReason.Arg())
		case 19:
			args = append(args, m.row.DecidedAt.Arg())
		case 20:
			args = append(args, m.row.Outcome)
		}
	}
	args = append(args, m.row.ID)
	return runtime.BatchOp{SQL: st.SQL, Args: args}, true
}

// DeleteOp is a delete as a queueable statement.
func DeleteOp(iD [16]byte) runtime.BatchOp {
	return runtime.BatchOp{SQL: deleteSQL, Args: []any{iD}}
}

// Table is the table these statements write, so a Unit can order a mixed
// batch by foreign key without knowing what any of them are.
const Table = "deviation_requests"

// stmtForKey compiles the UPDATE for one (dirty, expr) pair, once.
//
// The pair is the identity, not the dirty mask alone: the same column
// assigned a bound value and assigned a server-side expression are two
// different statements, and the arguments of one do not fit the other.
//
// ret picks the cache as well as the suffix. The batch path passes
// false — it cannot read rows back, so it must not ask for them.
func stmtForKey(k runtime.MaskKey, ret bool) *runtime.Stmt {
	cache := updCache
	if !ret {
		cache = updOpCache
	}
	if st := cache.Get(k); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		// An expression wins: a column set both ways cannot happen,
		// because each setter clears the other's bit.
		switch {
		case k.Expr&(1<<uint(i)) != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&(1<<uint(i)) != 0:
			set = append(set, setFrags[i])
		}
	}
	where := make([]runtime.Frag, 0, 2)
	where = append(where, pkFrags[:]...)
	// Only an expression needs reading back. A plain UPDATE already
	// knows every value it wrote, so it pays no RETURNING.
	suffix := ""
	if ret && k.Expr != 0 {
		suffix = updReturning
	}
	return cache.Put(k, runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
		{Lead: " WHERE ", Sep: " AND ", Frags: where},
	}, suffix))
}

// Update writes the assigned columns of one row.
//
// Assigning nothing is not an error and issues no statement — an UPDATE
// with an empty SET list is not valid SQL, and a caller looping over
// possibly-changed fields should not have to special-case the empty case.
//
// An assignment the DATABASE computes is read back in the same
// statement, so m.Row() is the row that now exists rather than the
// one that used to. A second SELECT would race every other writer,
// which is the same reason Insert reads its row back.
func (m *Mut) Update(ctx context.Context, ex runtime.Executor) error {
	if m.dirty == 0 && m.expr == 0 {
		return nil
	}
	st := stmtForKey(m.key(), true)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.ProjectID)
		case 2:
			args = append(args, m.row.Kind)
		case 3:
			args = append(args, m.row.Status)
		case 4:
			args = append(args, m.row.InstanceID.Arg())
		case 5:
			args = append(args, m.row.SourceDefinitionID.Arg())
		case 6:
			args = append(args, m.row.TargetDefinitionID.Arg())
		case 7:
			args = append(args, m.row.RequestedBy)
		case 8:
			args = append(args, m.row.RequestedByID)
		case 9:
			args = append(args, m.row.Reason)
		case 10:
			args = append(args, m.row.Command)
		case 11:
			args = append(args, m.row.Plan)
		case 12:
			args = append(args, m.row.Fingerprint)
		case 13:
			args = append(args, m.row.LiveKey.Arg())
		case 14:
			args = append(args, m.row.ApprovedInstances)
		case 15:
			args = append(args, m.row.ExpiresAt)
		case 16:
			args = append(args, m.row.DecidedBy.Arg())
		case 17:
			args = append(args, m.row.DecidedByID.Arg())
		case 18:
			args = append(args, m.row.DecisionReason.Arg())
		case 19:
			args = append(args, m.row.DecidedAt.Arg())
		case 20:
			args = append(args, m.row.Outcome)
		}
	}
	args = append(args, m.row.ID)
	if m.expr != 0 {
		return m.updateReturning(ctx, ex, st, args)
	}
	n, err := ex.Exec(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	m.dirty = 0
	m.expr = 0
	return nil
}

// updateReturning runs an UPDATE that let the database compute part of
// the row, and reads the whole row back into the staged copy.
//
// Every column, not just the computed ones: a trigger may have touched
// anything, and a staged row that is fresh in two fields and stale in
// the rest is harder to reason about than one that is simply current.
func (m *Mut) updateReturning(ctx context.Context, ex runtime.Executor, st *runtime.Stmt, args []any) error {
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrNoRow
	}
	// The staged row owns this arena, the way an inserted row does.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &m.row, &sl); err != nil {
		return err
	}
	if err := rows.Err(); err != nil {
		return err
	}
	m.dirty = 0
	m.expr = 0
	return nil
}

var deleteSQL = runtime.SpliceSections(deletePrefix, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: pkFrags[:]},
}, "").SQL

// Delete removes one row by primary key. A row that was already gone is
// runtime.ErrNoRow, not success: a caller deleting something that is not
// there usually has a bug, and swallowing it hides the bug.
func Delete(ctx context.Context, ex runtime.Executor, iD [16]byte) error {
	n, err := ex.Exec(ctx, deleteSQL, []any{iD})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}
